# -*- coding: utf-8 -*-
"""
=============================================================================
COLÉGIO PEDRO II - SISTEMA WEB DE LANÇAMENTO DA PROVA FINAL (PFV)
=============================================================================
Aplicação Web completa para navegadores (Chrome, Edge, Safari, Firefox).
Permite aos docentes lançar notas da Prova Final (PFV) com cálculo em tempo real
da nota necessária (Meta PFV) e da Média Final (MF).

Regra Oficial:
  - Aprovação Direta: Média Anual (MA) >= 6,0 (Dispensado da PFV)
  - Prova Final: Estudantes com MA < 6,0
  - Média Final: MF = (3 × MA + 2 × PFV) / 5
  - Aprovação na PFV: MF >= 5,0
  - Meta PFV: Nota mínima para atingir MF >= 5,0: (25 - 3 × MA) / 2
=============================================================================
"""

import streamlit as st
import pandas as pd
import openpyxl
from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
from openpyxl.utils import get_column_letter
import io
import json
import zlib
import base64
from decimal import Decimal, ROUND_HALF_UP

# Configuração da Página Web
st.set_page_config(
    page_title="Colégio Pedro II - Lançamento da Prova Final (PFV)",
    page_icon="🎓",
    layout="wide",
    initial_sidebar_state="expanded"
)

# Base de Dados Oficial das 38 Turmas (Ano Letivo 2026)
B64_DATA = """"""

@st.cache_data
def carregar_dados_turmas():
    compressed_bytes = base64.b64decode(B64_DATA.strip())
    json_bytes = zlib.decompress(compressed_bytes)
    data = json.loads(json_bytes.decode('utf-8'))
    return data['turmas'], data['orders']

turmas_data, turmas_orders = carregar_dados_turmas()
turmas_keys = sorted(list(turmas_data.keys()))

def arredondar_excel(valor):
    """Arredondamento padrão oficial do Excel (half away from zero) para 1 casa decimal."""
    try:
        return float(Decimal(str(valor)).quantize(Decimal('0.1'), rounding=ROUND_HALF_UP))
    except Exception:
        return round(float(valor), 1)

def calc_meta_pfv(ma):
    """Calcula a nota mínima na PFV para atingir MF >= 5,0: (25 - 3 * MA) / 2."""
    if ma is None or pd.isna(ma):
        return 5.0
    try:
        val_ma = float(ma)
        if val_ma >= 6.0:
            return 0.0 # Dispensado da PFV
        # Para MF >= 5,0: (3*MA + 2*PFV)/5 >= 5,0 => 2*PFV >= 25 - 3*MA
        meta = (25.0 - 3.0 * val_ma) / 2.0
        return max(0.0, arredondar_excel(meta))
    except (ValueError, TypeError):
        return 5.0

def calc_media_final_pfv(ma, pfv):
    """Calcula a Média Final após a Prova Final: MF = (3 * MA + 2 * PFV) / 5."""
    try:
        val_ma = float(ma)
        val_pfv = float(pfv)
        mf = arredondar_excel((val_ma * 3.0 + val_pfv * 2.0) / 5.0)
        return mf
    except (ValueError, TypeError):
        return None

def gerar_planilha_pfv_oficial(tcode, dcode, results):
    """Gera a planilha oficial detalhada da Prova Final no padrão institucional."""
    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = f"PFV_{dcode}"
    ws.sheet_view.showGridLines = True

    navy_fill = PatternFill(start_color="1F4E78", end_color="1F4E78", fill_type="solid")
    blue_header_fill = PatternFill(start_color="2F5496", end_color="2F5496", fill_type="solid")
    input_fill = PatternFill(start_color="DCE6F1", end_color="DCE6F1", fill_type="solid")
    soft_green_fill = PatternFill(start_color="E2EFDA", end_color="E2EFDA", fill_type="solid")
    soft_red_fill = PatternFill(start_color="FFC7CE", end_color="FFC7CE", fill_type="solid")
    soft_yellow_fill = PatternFill(start_color="FFF2CC", end_color="FFF2CC", fill_type="solid")
    gray_alt_fill = PatternFill(start_color="F9F9F9", end_color="F9F9F9", fill_type="solid")

    font_title = Font(name="Calibri", size=13, bold=True, color="FFFFFF")
    font_sub = Font(name="Calibri", size=10, italic=True, color="FFFFFF")
    font_header = Font(name="Calibri", size=10, bold=True, color="FFFFFF")
    font_data = Font(name="Calibri", size=10)
    font_bold = Font(name="Calibri", size=10, bold=True)
    font_ok = Font(name="Calibri", size=10, bold=True, color="276A3C")
    font_fail = Font(name="Calibri", size=10, bold=True, color="9C0006")

    thin_border = Border(
        left=Side(style='thin', color='D9D9D9'), right=Side(style='thin', color='D9D9D9'),
        top=Side(style='thin', color='D9D9D9'), bottom=Side(style='thin', color='D9D9D9')
    )

    # Títulos institucionais
    ws.merge_cells("A1:G1")
    ws.cell(row=1, column=1, value="COLÉGIO PEDRO II — RESULTADO OFICIAL DA PROVA FINAL (PFV)").font = font_title
    ws.cell(row=1, column=1).fill = navy_fill
    ws.cell(row=1, column=1).alignment = Alignment(horizontal="center", vertical="center")

    ws.merge_cells("A2:G2")
    ws.cell(row=2, column=1, value=f"TURMA: {tcode} | DISCIPLINA: {dcode} • Regra: MF = (3 × MA + 2 × PFV) / 5 ≥ 5,0").font = font_sub
    ws.cell(row=2, column=1).fill = blue_header_fill
    ws.cell(row=2, column=1).alignment = Alignment(horizontal="center", vertical="center")

    headers = ["Nº", "NOME DO ESTUDANTE", "MÉDIA ANUAL (MA)", "🎯 META PFV", "NOTA PFV", "MÉDIA FINAL (MF)", "SITUAÇÃO FINAL"]
    for c_idx, h in enumerate(headers, 1):
        cell = ws.cell(row=4, column=c_idx, value=h)
        cell.font = font_header
        cell.fill = navy_fill
        cell.alignment = Alignment(horizontal="center", vertical="center")

    for i, res in enumerate(results, 5):
        ws.cell(row=i, column=1, value=res['num']).alignment = Alignment(horizontal="center")
        ws.cell(row=i, column=1).font = font_data
        ws.cell(row=i, column=1).border = thin_border

        ws.cell(row=i, column=2, value=res['nome']).alignment = Alignment(horizontal="left")
        ws.cell(row=i, column=2).font = font_data
        ws.cell(row=i, column=2).border = thin_border

        c_ma = ws.cell(row=i, column=3, value=res['ma'])
        c_ma.alignment = Alignment(horizontal="center")
        c_ma.font = font_data
        c_ma.border = thin_border
        if isinstance(res['ma'], (int, float)):
            c_ma.number_format = '0.0'

        c_meta = ws.cell(row=i, column=4, value=res['meta_pfv'])
        c_meta.alignment = Alignment(horizontal="center")
        c_meta.font = font_bold
        c_meta.border = thin_border
        if isinstance(res['meta_pfv'], (int, float)):
            c_meta.number_format = '0.0'

        c_pfv = ws.cell(row=i, column=5)
        c_pfv.alignment = Alignment(horizontal="center")
        c_pfv.fill = input_fill
        c_pfv.border = thin_border
        c_pfv.font = font_bold
        if isinstance(res['pfv'], (int, float)):
            c_pfv.value = float(res['pfv'])
            c_pfv.number_format = '0.0'
        else:
            c_pfv.value = str(res['pfv'])

        c_mf = ws.cell(row=i, column=6)
        c_mf.alignment = Alignment(horizontal="center")
        c_mf.font = font_bold
        c_mf.border = thin_border
        if isinstance(res['mf'], (int, float)):
            c_mf.value = float(res['mf'])
            c_mf.number_format = '0.0'
            c_mf.fill = soft_green_fill if res['mf'] >= 5.0 else soft_red_fill
        else:
            c_mf.value = "-"

        c_st = ws.cell(row=i, column=7, value=res['status'])
        c_st.alignment = Alignment(horizontal="center")
        c_st.font = font_ok if "APROVADO" in str(res['status']) else (font_fail if "REPROVADO" in str(res['status']) else font_bold)
        c_st.border = thin_border
        if "APROVADO" in str(res['status']):
            c_st.fill = soft_green_fill
        elif "REPROVADO" in str(res['status']):
            c_st.fill = soft_red_fill
        elif "DISPENSADO" in str(res['status']):
            c_st.fill = soft_yellow_fill

        if i % 2 == 0:
            for c_k in [1, 2, 3, 4]:
                cell = ws.cell(row=i, column=c_k)
                if cell.fill.fill_type is None:
                    cell.fill = gray_alt_fill

    ws.column_dimensions['A'].width = 8
    ws.column_dimensions['B'].width = 42
    ws.column_dimensions['C'].width = 18
    ws.column_dimensions['D'].width = 16
    ws.column_dimensions['E'].width = 16
    ws.column_dimensions['F'].width = 18
    ws.column_dimensions['G'].width = 24

    ws.freeze_panes = "C5"

    output = io.BytesIO()
    wb.save(output)
    output.seek(0)
    return output

def gerar_planilha_2_colunas_pfv(tcode, dcode, results):
    """Gera a planilha compacta de 2 colunas para importação direta da secretaria."""
    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = "Lançamento PFV"
    ws.sheet_view.showGridLines = True

    navy_fill = PatternFill(start_color="1F4E78", end_color="1F4E78", fill_type="solid")
    blue_header_fill = PatternFill(start_color="2F5496", end_color="2F5496", fill_type="solid")
    input_fill = PatternFill(start_color="DCE6F1", end_color="DCE6F1", fill_type="solid")

    font_title = Font(name="Calibri", size=12, bold=True, color="FFFFFF")
    font_header = Font(name="Calibri", size=11, bold=True, color="FFFFFF")
    font_data = Font(name="Calibri", size=11)

    thin_border = Border(
        left=Side(style='thin', color='D9D9D9'), right=Side(style='thin', color='D9D9D9'),
        top=Side(style='thin', color='D9D9D9'), bottom=Side(style='thin', color='D9D9D9')
    )

    ws.cell(row=1, column=1, value="COLÉGIO PEDRO II - PLANILHA DE LANÇAMENTO DA PROVA FINAL (PFV)").font = font_title
    ws.cell(row=1, column=1).fill = navy_fill
    ws.merge_cells('A1:B1')

    ws.cell(row=2, column=1, value=f"TURMA: {tcode} | DISCIPLINA: {dcode}").font = font_title
    ws.cell(row=2, column=1).fill = blue_header_fill
    ws.merge_cells('A2:B2')

    ws.cell(row=4, column=1, value="Nº").font = font_header
    ws.cell(row=4, column=1).fill = navy_fill
    ws.cell(row=4, column=1).alignment = Alignment(horizontal="center")

    ws.cell(row=4, column=2, value=dcode).font = font_header
    ws.cell(row=4, column=2).fill = navy_fill
    ws.cell(row=4, column=2).alignment = Alignment(horizontal="center")

    for i, res in enumerate(results, 5):
        c1 = ws.cell(row=i, column=1, value=res['num'])
        c1.font = font_data
        c1.alignment = Alignment(horizontal="center")
        c1.border = thin_border

        c2 = ws.cell(row=i, column=2)
        c2.font = font_data
        c2.alignment = Alignment(horizontal="center")
        c2.border = thin_border
        c2.fill = input_fill

        val = res['pfv']
        if isinstance(val, (int, float)):
            c2.value = float(val)
            c2.number_format = '0.0'
        else:
            c2.value = str(val) if val not in [None, ""] else "(*)"

    ws.column_dimensions['A'].width = 10
    ws.column_dimensions['B'].width = 18

    output = io.BytesIO()
    wb.save(output)
    output.seek(0)
    return output

# =============================================================================
# INTERFACE PRINCIPAL DO STREAMLIT
# =============================================================================

st.title("🎓 Colégio Pedro II — Lançamento da Prova Final (PFV)")
st.markdown("##### Portal Docente Oficial • Metas de Aprovação e Média Final Ponderada (Peso 3 na MA + Peso 2 na PFV)")
st.write("---")

# Barra Lateral: Configurações e Turmas
with st.sidebar:
    st.header("⚙️ Painel do Docente")
    turma_selecionada = st.selectbox("Selecione a Turma:", turmas_keys, index=0)
    
    disciplinas_da_turma = turmas_orders.get(turma_selecionada, turmas_data[turma_selecionada]["subjects"])
    disciplina_selecionada = st.selectbox("Selecione a Disciplina:", disciplinas_da_turma, index=0)
    
    st.write("---")
    st.subheader("📂 Importar Médias Anuais (MA)")
    uploaded_file = st.file_uploader(
        "Carregar planilha com MAs (.xlsx, .csv ou Mapa Consolidado):",
        type=["xlsx", "xls", "csv"],
        help="Você pode carregar a planilha consolidada gerada pelo consolidador ou uma planilha própria com as notas de MA."
    )

    st.write("---")
    st.subheader("👁️ Modo de Exibição")
    modo_filtro = st.radio(
        "Visualizar na Lista:",
        ["🎯 Apenas Alunos em Prova Final (MA < 6,0)", "👥 Todos os Alunos da Turma"],
        index=0
    )

    st.write("---")
    st.info(
        "📌 **Regras Oficiais da Prova Final**:\n\n"
        "• **Aprovação Direta**: MA ≥ 6,0 (Dispensado de PFV)\n"
        "• **Convocado para PFV**: MA < 6,0\n"
        "• **Média Final**: `MF = (3 × MA + 2 × PFV) / 5`\n"
        "• **Critério de Aprovação**: `MF ≥ 5,0`\n"
        "• **Meta PFV**: `(25 - 3 × MA) / 2`"
    )

# Processar arquivo de MAs importado (se houver)
imported_mas = {}

if uploaded_file is not None:
    try:
        if uploaded_file.name.endswith('.csv'):
            df_imp = pd.read_csv(uploaded_file)
            for _, r in df_imp.iterrows():
                vals = list(r.values)
                if len(vals) >= 2:
                    try:
                        n_id = int(vals[0])
                        v = float(str(vals[1]).replace(',', '.'))
                        if 0.0 <= v <= 10.0:
                            imported_mas[n_id] = v
                    except (ValueError, TypeError):
                        pass
            st.sidebar.success(f"MAs importadas via CSV para {len(imported_mas)} estudantes!")
        else:
            # Excel: pode ser Mapa Consolidado (com aba Média Final) ou planilha avulsa
            wb_imp = openpyxl.load_workbook(uploaded_file, data_only=True)
            ws_target = wb_imp.active
            if "Média Final" in wb_imp.sheetnames:
                ws_target = wb_imp["Média Final"]
            elif "Consolidado Final 1ª e 2ª Cert" in wb_imp.sheetnames:
                ws_target = wb_imp["Consolidado Final 1ª e 2ª Cert"]

            # Procurar coluna da disciplina
            col_disc = None
            for c in range(1, ws_target.max_column + 1):
                val_h = str(ws_target.cell(row=4, column=c).value or ws_target.cell(row=3, column=c).value or "").strip().upper()
                if disciplina_selecionada.upper() in val_h:
                    col_disc = c
                    break

            if col_disc:
                for r in range(5, ws_target.max_row + 1):
                    n_val = ws_target.cell(row=r, column=1).value
                    v_val = ws_target.cell(row=r, column=col_disc).value
                    if n_val is not None:
                        try:
                            n_id = int(n_val)
                            if v_val is not None and str(v_val).strip() not in ["", "(*)", "-", "None"]:
                                v_float = float(str(v_val).replace(',', '.'))
                                if 0.0 <= v_float <= 10.0:
                                    imported_mas[n_id] = arredondar_excel(v_float)
                        except (ValueError, TypeError):
                            pass
                st.sidebar.success(f"Notas da disciplina {disciplina_selecionada} lidas com sucesso para {len(imported_mas)} alunos!")
            else:
                # Ler simplesmente coluna 1 como Nº e coluna 2 como Nota
                for r in range(1, ws_target.max_row + 1):
                    n_val = ws_target.cell(row=r, column=1).value
                    v_val = ws_target.cell(row=r, column=2).value
                    if n_val is not None:
                        try:
                            n_id = int(n_val)
                            if v_val is not None and str(v_val).strip() not in ["", "(*)", "-", "None"]:
                                v_float = float(str(v_val).replace(',', '.'))
                                if 0.0 <= v_float <= 10.0:
                                    imported_mas[n_id] = arredondar_excel(v_float)
                        except (ValueError, TypeError):
                            pass
                if imported_mas:
                    st.sidebar.success(f"Planilha lida com sucesso ({len(imported_mas)} notas encontradas)!")
    except Exception as err:
        st.sidebar.error(f"Erro ao ler arquivo: {err}")

# Carregar Estudantes da Turma Selecionada
students = turmas_data[turma_selecionada]["students"]

# Montagem dos Dados Iniciais da Tabela
raw_table = []
for st_item in students:
    num = st_item["num"]
    nome = st_item["nome"]
    coc = st_item.get("coc", "")
    
    # MA: vinda do arquivo carregado ou padrão inicial
    ma_val = imported_mas.get(num, None)
    
    # Se ainda não houver arquivo carregado, deixamos 5.0 como sugestão editável padrão
    if ma_val is None:
        ma_val = 5.0
        
    meta = calc_meta_pfv(ma_val)
    
    raw_table.append({
        "num": num,
        "coc": coc,
        "nome": nome,
        "ma": float(ma_val),
        "meta": meta,
        "pfv": None
    })

df_all = pd.DataFrame(raw_table)

# Aplicar o Filtro Escolhido pelo Docente
if "Apenas Alunos em Prova Final" in modo_filtro:
    df_filtered = df_all[df_all["ma"] < 6.0].copy()
    sub_title_extra = f"Exibindo apenas convocados para PFV (MA < 6,0) • Total: {len(df_filtered)} de {len(df_all)} estudantes"
else:
    df_filtered = df_all.copy()
    sub_title_extra = f"Exibindo turma completa ({len(df_filtered)} estudantes)"

st.subheader(f"📋 Lançamento de Notas — Turma {turma_selecionada} • {disciplina_selecionada}")
st.caption(sub_title_extra)

if len(df_filtered) == 0:
    st.success(f"🎉 Parabéns! Todos os estudantes da Turma {turma_selecionada} em {disciplina_selecionada} obtiveram Média Anual ≥ 6,0 e estão Aprovados Direto!")
    edited_df = pd.DataFrame(columns=["num", "nome", "ma", "meta", "pfv"])
else:
    # Grid de Edição Interativo (Streamlit data_editor)
    edited_df = st.data_editor(
        df_filtered[["num", "nome", "ma", "meta", "pfv"]],
        column_config={
            "num": st.column_config.NumberColumn("Nº", disabled=True, width="small"),
            "nome": st.column_config.TextColumn("Nome do Estudante", disabled=True, width="large"),
            "ma": st.column_config.NumberColumn(
                "Média Anual (MA)",
                min_value=0.0,
                max_value=10.0,
                step=0.1,
                format="%.1f",
                help="Média Ponderada da 1ª e 2ª Certificações. Editável caso precise ajustar.",
                width="medium"
            ),
            "meta": st.column_config.NumberColumn(
                "🎯 Meta PFV (MF ≥ 5,0)",
                disabled=True,
                format="%.1f",
                help="Nota mínima que o aluno precisa tirar na Prova Final para ser Aprovado.",
                width="medium"
            ),
            "pfv": st.column_config.NumberColumn(
                "Nota Prova Final (PFV)",
                min_value=0.0,
                max_value=10.0,
                step=0.1,
                format="%.1f",
                help="Digite a nota obtida na prova final (de 0,0 a 10,0).",
                width="medium"
            )
        },
        hide_index=True,
        use_container_width=True
    )

# Processamento e Cálculo em Tempo Real
final_results = []
count_total_turma = len(df_all)
count_em_pfv = len(df_all[df_all["ma"] < 6.0])
count_pfv_lancadas = 0
count_aprovados_pfv = 0
count_reprovados_pfv = 0

# Criamos um mapa atualizado a partir da edição
edited_map = {}
if not edited_df.empty:
    for _, r in edited_df.iterrows():
        edited_map[int(r["num"])] = {
            "ma": r["ma"],
            "pfv": r["pfv"]
        }

for _, r_orig in df_all.iterrows():
    n_id = int(r_orig["num"])
    nome_st = r_orig["nome"]
    coc_st = r_orig["coc"]
    
    if n_id in edited_map:
        curr_ma = edited_map[n_id]["ma"]
        curr_pfv = edited_map[n_id]["pfv"]
    else:
        curr_ma = r_orig["ma"]
        curr_pfv = None
        
    meta_val = calc_meta_pfv(curr_ma)
    
    if curr_ma >= 6.0:
        status_txt = f"🟢 DISPENSADO DA PFV (MA = {curr_ma:.1f})"
        mf_val = curr_ma
        pfv_disp = "—"
    else:
        if pd.isna(curr_pfv) or curr_pfv is None:
            status_txt = "⚪ PENDENTE DE NOTA"
            mf_val = None
            pfv_disp = ""
        else:
            val_p = arredondar_excel(curr_pfv)
            pfv_disp = val_p
            mf_val = calc_media_final_pfv(curr_ma, val_p)
            count_pfv_lancadas += 1
            if mf_val is not None:
                if mf_val >= 5.0:
                    status_txt = "🟢 APROVADO NA PFV"
                    count_aprovados_pfv += 1
                else:
                    status_txt = "🔴 REPROVADO"
                    count_reprovados_pfv += 1
            else:
                status_txt = "⚪ PENDENTE DE NOTA"
                
    final_results.append({
        "num": n_id,
        "coc": coc_st,
        "nome": nome_st,
        "ma": curr_ma,
        "meta_pfv": meta_val,
        "pfv": pfv_disp,
        "mf": mf_val,
        "status": status_txt
    })

# Tabela de Resultados Imediatos (Feedback visual instantâneo)
st.write("---")
st.subheader("🎯 Acompanhamento em Tempo Real dos Resultados")

display_rows = []
for r in final_results:
    if "Apenas Alunos em Prova Final" in modo_filtro and r["ma"] >= 6.0:
        continue
    display_rows.append({
        "Nº": r["num"],
        "Nome do Estudante": r["nome"],
        "Média Anual (MA)": f"{r['ma']:.1f}",
        "🎯 Meta PFV": f"{r['meta_pfv']:.1f}" if isinstance(r['meta_pfv'], (int, float)) else str(r['meta_pfv']),
        "Nota da PFV": f"{float(r['pfv']):.1f}" if isinstance(r['pfv'], (int, float)) else str(r['pfv']),
        "Média Final (MF)": f"{float(r['mf']):.1f}" if isinstance(r['mf'], (int, float)) else "—",
        "Situação Acadêmica": r["status"]
    })

if display_rows:
    st.dataframe(pd.DataFrame(display_rows), use_container_width=True, hide_index=True)
else:
    st.info("Nenhum estudante a exibir no filtro atual.")

# Painel de Indicadores no Rodapé
st.write("---")
st.subheader("📊 Indicadores da Turma na Prova Final")
m1, m2, m3, m4, m5 = st.columns(5)
m1.metric("Total de Alunos", count_total_turma)
m2.metric("Convocados p/ PFV (MA < 6)", count_em_pfv)
m3.metric("Notas PFV Lançadas", count_pfv_lancadas)
m4.metric("Aprovados pós-PFV (MF ≥ 5)", count_aprovados_pfv)
m5.metric("Reprovados (MF < 5)", count_reprovados_pfv)

st.write("---")

# Seção de Download dos Arquivos Oficiais
st.subheader("💾 Exportar Resultados para a Direção / Secretaria")

planilha_completa = gerar_planilha_pfv_oficial(turma_selecionada, disciplina_selecionada, final_results)
planilha_2_col = gerar_planilha_2_colunas_pfv(turma_selecionada, disciplina_selecionada, final_results)

btn_col1, btn_col2 = st.columns(2)

